// === Daily Briefing Aggregator ===
// Aggregates emails and calendar events from multiple sources
// CUSTOMIZE: Update VIP_EMAILS, VIP_NAMES, and keywords for your needs

const now = new Date();
const _errors = [];

// === CUSTOMIZE: VIP Contacts ===
// Add email addresses of people whose messages should always be flagged
const VIP_EMAILS = [
  'boss@company.com',
  'important-client@example.com',
  'spouse@family.com'
];

const VIP_NAMES = {
  'boss@company.com': 'Your Boss',
  'important-client@example.com': 'Important Client',
  'spouse@family.com': 'Spouse'
};

// === CUSTOMIZE: High Priority Keywords ===
// Emails containing these words get flagged HIGH priority
const HIGH_PRIORITY_KEYWORDS = [
  'urgent', 'ASAP', 'time-sensitive', 'deadline', 'expires',
  'expiring', 'immediately', 'action required', 'signature needed',
  'sign by', 'due by', 'past due', 'emergency', 'critical'
];

// === CUSTOMIZE: Medium Priority Keywords ===
const MEDIUM_PRIORITY_KEYWORDS = [
  'important', 'review', 'follow up', 'reminder', 'meeting',
  'schedule', 'confirm', 'approval', 'request', 'update'
];

// === Helper Functions ===
function isVipSender(fromField) {
  const fromLower = (fromField || '').toLowerCase();
  return VIP_EMAILS.some(vip => fromLower.includes(vip));
}

function getVipName(fromField) {
  const fromLower = (fromField || '').toLowerCase();
  for (const [email, name] of Object.entries(VIP_NAMES)) {
    if (fromLower.includes(email)) return name;
  }
  return null;
}

function matchKeyword(subject, snippet, keywords) {
  const text = ((subject || '') + ' ' + (snippet || '')).toLowerCase();
  return keywords.find(kw => text.includes(kw.toLowerCase())) || null;
}

function flagPriority(email) {
  if (isVipSender(email.from)) {
    email.priority = 'VIP';
    email.priority_reason = 'VIP contact: ' + (getVipName(email.from) || email.from);
  } else {
    const highMatch = matchKeyword(email.subject, email.snippet, HIGH_PRIORITY_KEYWORDS);
    if (highMatch) {
      email.priority = 'HIGH';
      email.priority_reason = 'Keyword: ' + highMatch;
    } else {
      const medMatch = matchKeyword(email.subject, email.snippet, MEDIUM_PRIORITY_KEYWORDS);
      if (medMatch) {
        email.priority = 'MEDIUM';
        email.priority_reason = 'Keyword: ' + medMatch;
      } else {
        email.priority = 'NORMAL';
        email.priority_reason = '';
      }
    }
  }
  return email;
}

// === Parse Gmail messages ===
function parseGmailMessage(msg) {
  const j = msg.json || {};
  return {
    id: j.id || '',
    from: j.From || j.from || '',
    subject: j.Subject || j.subject || '(no subject)',
    date: j.Date || j.date || j.internalDate || '',
    snippet: j.snippet || '',
    is_unread: (j.labelIds || j.labels || []).some(l =>
      (typeof l === 'string' ? l : l.id || '') === 'UNREAD'
    ),
    labels: (j.labelIds || j.labels || []).map(l =>
      typeof l === 'string' ? l : l.id || l.name || ''
    ),
    thread_id: j.threadId || ''
  };
}

// === Parse IMAP messages ===
function parseImapMessage(msg) {
  const j = msg.json || {};
  return {
    from: j.from || j.header?.from?.[0] || '',
    subject: j.subject || j.header?.subject?.[0] || '',
    date: j.date || j.header?.date?.[0] || '',
    snippet: (j.text || j.textPlain || j.body || '').substring(0, 200),
    is_unread: true
  };
}

// === Parse calendar events ===
function parseCalendarEvent(evt, source) {
  const j = evt.json || {};
  let videoLink = '';
  if (j.conferenceData?.entryPoints) {
    const video = j.conferenceData.entryPoints.find(e => e.entryPointType === 'video');
    if (video) videoLink = video.uri;
  }
  if (!videoLink && j.hangoutLink) videoLink = j.hangoutLink;
  return {
    source: source,
    title: j.summary || j.title || '',
    start: j.start?.dateTime || j.start?.date || j.start || '',
    end: j.end?.dateTime || j.end?.date || j.end || '',
    attendees: (j.attendees || []).map(a => ({
      email: a.email, name: a.displayName || '', status: a.responseStatus || ''
    })),
    location: j.location || '',
    video_link: videoLink,
    description: (j.description || '').substring(0, 500),
    is_all_day: !!(j.start?.date && !j.start?.dateTime)
  };
}

// === Collect items by _source tag ===
const allItems = $input.all() || [];

function getTaggedItems(sourceTag) {
  try {
    return allItems.filter(i => i.json?._source === sourceTag);
  } catch(e) {
    _errors.push({ source: sourceTag, error: e.message });
    return [];
  }
}

// === Process each source ===
let gmailPrimary = [], gmailWork = [], imapAdditional = [];
let calPrimary = [], calWork = [], calTomorrow = [];

try { gmailPrimary = getTaggedItems('gmail_primary').map(parseGmailMessage).map(flagPriority); }
catch(e) { _errors.push({ source: 'gmail_primary', error: e.message }); }

try { gmailWork = getTaggedItems('gmail_work').map(parseGmailMessage).map(flagPriority); }
catch(e) { _errors.push({ source: 'gmail_work', error: e.message }); }

try { imapAdditional = getTaggedItems('imap_additional').map(parseImapMessage).map(flagPriority); }
catch(e) { _errors.push({ source: 'imap_additional', error: e.message }); }

try { calPrimary = getTaggedItems('gcal_primary').map(e => parseCalendarEvent(e, 'primary')); }
catch(e) { _errors.push({ source: 'gcal_primary', error: e.message }); }

try { calWork = getTaggedItems('gcal_work').map(e => parseCalendarEvent(e, 'work')); }
catch(e) { _errors.push({ source: 'gcal_work', error: e.message }); }

try { calTomorrow = getTaggedItems('gcal_tomorrow').map(e => parseCalendarEvent(e, 'primary')); }
catch(e) { _errors.push({ source: 'gcal_tomorrow', error: e.message }); }

// === Compute stats ===
const unreadPrimary = gmailPrimary.filter(e => e.is_unread).length;
const unreadWork = gmailWork.filter(e => e.is_unread).length;
const unreadAdditional = imapAdditional.length;

const allEmails = [...gmailPrimary, ...gmailWork, ...imapAdditional];
const priorityEmails = allEmails.filter(e =>
  e.priority === 'VIP' || e.priority === 'HIGH' || e.priority === 'MEDIUM'
);

const allCalToday = [...calPrimary, ...calWork].sort((a, b) =>
  new Date(a.start) - new Date(b.start)
);

const upcomingMeetings = allCalToday.filter(e =>
  !e.is_all_day && new Date(e.start) > now
);
const nextMeetingMinutes = upcomingMeetings.length > 0
  ? Math.round((new Date(upcomingMeetings[0].start) - now) / 60000)
  : null;

// === Build response ===
return [{
  json: {
    success: true,
    data: {
      generated_at: now.toISOString(),
      period: 'last_24_hours',
      email: {
        primary_gmail: gmailPrimary,
        work_gmail: gmailWork,
        additional_imap: imapAdditional
      },
      priority_emails: priorityEmails,
      calendar: {
        today: allCalToday,
        tomorrow_first: calTomorrow.length > 0 ? calTomorrow[0] : null
      },
      summary: {
        total_unread: unreadPrimary + unreadWork + unreadAdditional,
        unread_by_account: {
          primary_gmail: unreadPrimary,
          work_gmail: unreadWork,
          additional_imap: unreadAdditional
        },
        priority_count: priorityEmails.length,
        meetings_today: allCalToday.length,
        next_meeting_in_minutes: nextMeetingMinutes,
        next_meeting: upcomingMeetings.length > 0
          ? upcomingMeetings[0].title + ' at ' + upcomingMeetings[0].start
          : 'No upcoming meetings today'
      },
      _errors: _errors,
      _sources_ok: 6 - _errors.length,
      _sources_total: 6
    },
    error: null
  }
}];
